import{_ as t,o as h,c as o,a3 as g}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Kho / Xưởng","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/kho-xuong.md","filePath":"chuc-nang/kho-xuong.md","lastUpdated":null}'),a={name:"chuc-nang/kho-xuong.md"};function c(r,n,s,i,e,l){return h(),o("div",null,[...n[0]||(n[0]=[g('<h1 id="kho-xuong" tabindex="-1">Kho / Xưởng <a class="header-anchor" href="#kho-xuong" aria-label="Permalink to &quot;Kho / Xưởng&quot;">​</a></h1><p>Module quản lý <strong>công nhân kho &amp; xưởng sản xuất</strong>: chấm công bằng ảnh mặt + GPS, ghi sản lượng theo sản phẩm, quản lý vật tư, duyệt nghỉ phép / ứng lương, bảng tin nội bộ và báo cáo tháng.</p><p>Khác với chấm công văn phòng, công nhân kho <strong>không dùng tài khoản AssetFlow</strong>. Họ đăng nhập vào một mini-app riêng bằng <strong>số căn cước + mã PIN 6 số</strong>, không cần email, chạy tốt trên điện thoại phổ thông.</p><div class="info custom-block"><p class="custom-block-title">Ai dùng được</p><table tabindex="0"><thead><tr><th>Vai trò</th><th>Vào đâu</th><th>Làm gì</th></tr></thead><tbody><tr><td><strong>Công nhân</strong></td><td><code>assetflow.fadoai.com/warehouse</code></td><td>Chấm công, xem bảng công, xem sản lượng, đọc bảng tin, xin nghỉ / ứng lương</td></tr><tr><td><strong>Quản lý kho / Admin</strong></td><td>Menu <strong>Kho / Xưởng</strong> trong app chính</td><td>Tạo kho, cấu hình, quản lý công nhân, duyệt yêu cầu, xuất báo cáo</td></tr><tr><td><strong>Màn hình cổng kho</strong></td><td><code>/warehouse/gate?wh=MÃ_KHO</code></td><td>Hiện mã QR động cho công nhân quét khi GPS lỗi</td></tr></tbody></table></div><div class="warning custom-block"><p class="custom-block-title">Bắt buộc có quyền</p><p>Module này dùng RBAC <strong>nghiêm ngặt</strong>: không được tick quyền <strong>Xem</strong> của module <em>Kho / Xưởng</em> thì không thấy dữ liệu — <strong>kể cả Super Admin</strong>. Quyền <strong>Thêm</strong> (tạo kho) và <strong>Sửa</strong> (cấu hình kho) là hai quyền <strong>tách biệt</strong>. Xem thêm ở <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p></div><h2 id="phan-1-—-app-cua-cong-nhan" tabindex="-1">Phần 1 — App của công nhân <a class="header-anchor" href="#phan-1-—-app-cua-cong-nhan" aria-label="Permalink to &quot;Phần 1 — App của công nhân&quot;">​</a></h2><h3 id="đang-nhap" tabindex="-1">Đăng nhập <a class="header-anchor" href="#đang-nhap" aria-label="Permalink to &quot;Đăng nhập&quot;">​</a></h3><p>Công nhân mở <code>assetflow.fadoai.com/warehouse</code> trên điện thoại (nên <strong>Thêm vào màn hình chính</strong> để dùng như một app).</p><ol><li>Nhập <strong>số căn cước</strong> (do quản lý kho khai khi tạo hồ sơ công nhân).</li><li>Nhập <strong>mã PIN 6 chữ số</strong>.</li><li>Lần đăng nhập đầu tiên, hệ thống <strong>bắt buộc đổi PIN mới</strong> trước khi vào.</li></ol><h3 id="cham-cong-tab-cham-cong" tabindex="-1">Chấm công (tab Chấm công) <a class="header-anchor" href="#cham-cong-tab-cham-cong" aria-label="Permalink to &quot;Chấm công (tab Chấm công)&quot;">​</a></h3><p>Chấm công kho có <strong>2 lớp kiểm soát</strong>, chặt hơn chấm công văn phòng:</p><ol><li><strong>Vị trí GPS</strong> — công nhân phải đứng trong <strong>bán kính</strong> đã cấu hình quanh kho (ví dụ 100m) và bật định vị. Nếu kho chưa khai toạ độ thì bỏ qua bước kiểm tra này.</li><li><strong>Ảnh mặt</strong> — <strong>bắt buộc chụp ảnh bằng camera trước</strong> ngay lúc bấm. Không thể chọn ảnh có sẵn trong thư viện, nên không chấm hộ được.</li></ol><p>Bấm <strong>Check-in (chụp ảnh)</strong> khi vào ca và <strong>Check-out (chụp ảnh)</strong> khi hết ca. Có thể chọn <strong>ca làm việc</strong>, hoặc để <em>Theo ca mặc định</em> của kho.</p><div class="tip custom-block"><p class="custom-block-title">GPS lỗi thì làm sao?</p><p>Trong xưởng có mái tôn, tầng hầm hoặc máy cũ, GPS hay chập chờn. Khi đó bấm <strong>GPS lỗi? Quét QR tại cổng kho</strong> rồi quét mã QR đang hiển thị trên màn hình treo ở cổng. Quét xong, hệ thống <strong>bỏ qua kiểm tra GPS</strong> — nhưng <strong>vẫn bắt buộc chụp ảnh mặt</strong>.</p><p>Mã QR ở cổng <strong>tự đổi mỗi 10 phút</strong>, nên không thể chụp màn hình gửi cho người khác chấm hộ.</p></div><h3 id="bang-cong-·-san-luong-·-bang-tin" tabindex="-1">Bảng công · Sản lượng · Bảng tin <a class="header-anchor" href="#bang-cong-·-san-luong-·-bang-tin" aria-label="Permalink to &quot;Bảng công · Sản lượng · Bảng tin&quot;">​</a></h3><ul><li><strong>Bảng công</strong> — công nhân tự xem lại lịch sử vào/ra của mình trong tháng.</li><li><strong>Sản lượng</strong> — xem số lượng sản phẩm mình đã làm (do quản lý ghi nhận).</li><li><strong>Bảng tin</strong> — thông báo nội bộ do quản lý kho đăng (lịch nghỉ lễ, quy định mới…).</li></ul><h3 id="gui-yeu-cau-tab-yeu-cau" tabindex="-1">Gửi yêu cầu (tab Yêu cầu) <a class="header-anchor" href="#gui-yeu-cau-tab-yeu-cau" aria-label="Permalink to &quot;Gửi yêu cầu (tab Yêu cầu)&quot;">​</a></h3><ul><li><strong>Xin nghỉ</strong> — chọn <em>Từ ngày</em> → <em>Đến ngày</em> + lý do.</li><li><strong>Ứng lương</strong> — nhập <em>số tiền muốn ứng</em> + lý do. Nút này <strong>chỉ hiện khi kho bật tính năng ứng lương</strong> trong cấu hình.</li></ul><p>Yêu cầu gửi lên chờ quản lý duyệt ở tab <strong>Duyệt</strong> bên Warehouse Admin.</p><h2 id="phan-2-—-quan-ly-kho-trong-app-chinh" tabindex="-1">Phần 2 — Quản lý kho (trong app chính) <a class="header-anchor" href="#phan-2-—-quan-ly-kho-trong-app-chinh" aria-label="Permalink to &quot;Phần 2 — Quản lý kho (trong app chính)&quot;">​</a></h2><p>Vào menu <strong>Kho / Xưởng</strong> để xem tổng quan tất cả kho: số công nhân, tình hình chấm công, sản lượng. Từ đây bấm <strong>Mở Warehouse Admin</strong> để vào khu làm việc chi tiết, hoặc <strong>Tạo kho mới</strong> (cần quyền <em>Thêm</em>).</p><h3 id="cau-hinh-kho" tabindex="-1">Cấu hình kho <a class="header-anchor" href="#cau-hinh-kho" aria-label="Permalink to &quot;Cấu hình kho&quot;">​</a></h3><p>Bấm biểu tượng cấu hình trên thẻ kho (cần quyền <em>Sửa</em>):</p><table tabindex="0"><thead><tr><th>Mục</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td><strong>Tên kho · Địa chỉ · Công ty chủ quản</strong></td><td>Thông tin định danh kho</td></tr><tr><td><strong>Vĩ độ (lat) · Kinh độ (lng)</strong></td><td>Toạ độ kho — lấy từ Google Maps</td></tr><tr><td><strong>Bán kính (m)</strong></td><td>Phạm vi cho phép chấm công quanh toạ độ trên</td></tr><tr><td><strong>Giữ ảnh (ngày)</strong></td><td>Ảnh mặt lúc chấm công tự xoá sau số ngày này</td></tr><tr><td><strong>Email nhận báo cáo tháng</strong></td><td>Nhiều email cách nhau bằng dấu phẩy</td></tr><tr><td><strong>Ca làm việc</strong></td><td>Khai các ca (tên ca + giờ)</td></tr><tr><td><strong>Sản phẩm</strong></td><td>Danh mục sản phẩm + đơn vị tính, dùng để ghi sản lượng</td></tr><tr><td><strong>Quản lý kho</strong></td><td>Gán user AssetFlow (theo email) làm quản lý kho này</td></tr><tr><td><strong>Ứng lương</strong></td><td>Bật/tắt quyền công nhân xin ứng lương</td></tr></tbody></table><h3 id="cac-tab-trong-warehouse-admin" tabindex="-1">Các tab trong Warehouse Admin <a class="header-anchor" href="#cac-tab-trong-warehouse-admin" aria-label="Permalink to &quot;Các tab trong Warehouse Admin&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Công nhân</strong></td><td>Thêm/sửa hồ sơ công nhân (căn cước, PIN), gán vào kho</td></tr><tr><td><strong>Chấm công</strong></td><td>Xem lượt chấm kèm <strong>ảnh mặt</strong> đã chụp, đối chiếu gian lận</td></tr><tr><td><strong>Sản lượng</strong></td><td>Ghi nhận số lượng sản phẩm từng công nhân làm được</td></tr><tr><td><strong>Vật tư</strong></td><td>Quản lý vật tư trong kho: nhập/xuất, tồn kho</td></tr><tr><td><strong>Xếp hạng</strong></td><td>Bảng xếp hạng công nhân theo sản lượng</td></tr><tr><td><strong>Duyệt</strong></td><td>Duyệt/từ chối đơn nghỉ phép &amp; ứng lương</td></tr><tr><td><strong>Bảng tin</strong></td><td>Đăng thông báo cho công nhân đọc trong app</td></tr><tr><td><strong>Báo cáo</strong></td><td>Xuất báo cáo tháng (file Excel)</td></tr></tbody></table><h2 id="man-hinh-qr-o-cong-kho" tabindex="-1">Màn hình QR ở cổng kho <a class="header-anchor" href="#man-hinh-qr-o-cong-kho" aria-label="Permalink to &quot;Màn hình QR ở cổng kho&quot;">​</a></h2><p>Treo một tablet hoặc màn hình cũ ở cổng, mở đường dẫn:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://assetflow.fadoai.com/warehouse/gate?wh=MÃ_KHO</span></span></code></pre></div><p>Trang này hiện mã QR cỡ lớn, <strong>tự làm mới mỗi phút</strong> và <strong>mã đổi mỗi 10 phút</strong>. Không cần đăng nhập, cứ để mở suốt ngày.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Công nhân có cần email công ty không?</strong> Không. Họ đăng nhập bằng <strong>căn cước + PIN</strong>, hoàn toàn tách khỏi hệ tài khoản nhân viên văn phòng.</p><p><strong>Công nhân quên PIN thì sao?</strong> Quản lý kho vào tab <strong>Công nhân</strong> đặt lại PIN. Lần đăng nhập kế tiếp công nhân sẽ bị buộc đổi PIN mới.</p><p><strong>Có chấm công hộ được không?</strong> Rất khó: phải chụp ảnh mặt bằng camera trước ngay tại thời điểm chấm (không chọn được ảnh cũ), lại phải đứng trong bán kính kho hoặc quét được mã QR ở cổng — mã này đổi 10 phút một lần.</p><p><strong>Ảnh mặt lưu bao lâu?</strong> Theo số ngày khai ở ô <strong>Giữ ảnh (ngày)</strong> trong cấu hình kho; quá hạn hệ thống tự xoá.</p><p><strong>Chấm công kho có chung dữ liệu với chấm công văn phòng không?</strong> Không. Đây là hệ chấm công riêng cho công nhân, không nằm trong <a href="/help/chuc-nang/cham-cong.html">Dữ liệu chấm công</a> của nhân viên văn phòng.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a> · <a href="/help/chuc-nang/cham-cong.html">Chấm công (văn phòng)</a> · <a href="/help/chuc-nang/da-cong-ty.html">Đa công ty</a></p>',38)])])}const m=t(a,[["render",c]]);export{u as __pageData,m as default};
